standard_library.install_aliases()
logger = BackgroundLogger.Instance()


class ScapyTool(ToolBase):
    TOOL = "scapy"

    def __init__(self, device):
        self.device = device
        self.session = None
        self.root = None
        self.sudo_dict = {'root': '', 'non-root': 'sudo'}
        # self.base_interface = get_config_variable(['generators', self.device, 'interface'])
        self.bts_id = get_config_variable(['bts_id'])

    def traffic_setup(self):
        logger.info("Setting up traffic...")
        ip, user, password, prompt = self._get_scapy_credentials()
        self.session = self.login_to_scapy_pc(user, ip, password, prompt)
        self.home_path = self._get_scapy_pc_home_path(user)
        send_traffic_script_name = 'scapy_send_traffic.py'
        scapy_script = os.path.abspath(os.path.join(__file__, os.pardir, send_traffic_script_name))
        self.session.put_file(scapy_script, "~/{}".format(send_traffic_script_name))

    def _get_scapy_credentials(self):
        ip = get_config_variable(['generators', self.device, 'ip'])
        user = get_config_variable(['generators', self.device, 'user'])
        password = get_config_variable(['generators', self.device, 'password'])
        prompt = get_config_variable(['generators', self.device, 'prompt'])
        return ip, user, password, prompt

    def traffic_start(self, profile):
        self.render_get_packet_from_user_script(profile)
        logger.debug("starting traffic....")
        self.pad1 = self.bts_id[:4]
        self.pad2 = datetime.now().strftime('%M%S')
        self.pad = str(int(self.pad1) + int(self.pad2))[:4]
        self.pad += 'a'*(4-len(self.pad))
        speed, duration = self._send_traffic(profile)
        return speed, duration

    def render_get_packet_from_user_script(self, profile):
        pkt_details = dict(get_config_variable(['traffic_profiles', profile]))
        template_file_name = 'get_packet_from_user.template'
        rendered_file_name = 'get_packet_from_user.py'
        template_file = os.path.abspath(os.path.join(__file__, os.pardir, 'resources', template_file_name))
        loader = FileSystemLoader(os.path.dirname(template_file))
        env = Environment(loader=loader)
        template = env.get_template(template_file_name)
        rendered_content = template.render(pkt_details, command=pkt_details.get('command', ''))
        logger.debug('rendered_content: {}\n'.format(rendered_content))
        rendered_file = 'execution_logs/{}'.format(rendered_file_name)
        if not os.path.exists(os.path.dirname(rendered_file)):
            os.makedirs(os.path.dirname(rendered_file))
        with open(rendered_file, 'w') as f_file:
            f_file.write(rendered_content)
        self.session.put_file(rendered_file, "~/{}".format(rendered_file_name))

    def traffic_stop(self):
        pass

    def traffic_teardown(self):
        logger.debug("performing traffic teardown...")
        # self.exit_scapy_interface()
        self.session.close_all_connections()

    def build_scapy_send_traffic_script_command(self, profile):
        pkt_details = dict(get_config_variable(['traffic_profiles', profile]))
        cmd = 'sudo python scapy_send_traffic.py '
        cmd += '--interface {} '.format(get_config_variable(['generators', self.device, 'interface']))
        cmd += '--ip_version {} '.format(pkt_details.get("ip_version"))
        cmd += '--malformed {} '.format(pkt_details.get("malformed"))
        cmd += '--frame_size {} '.format(pkt_details.get("frame_size"))
        cmd += '--protocol {} '.format(pkt_details.get("protocol"))
        cmd += '--src_port {} '.format(pkt_details.get("src_port"))
        cmd += '--dst_port {} '.format(pkt_details.get("dst_port"))
        cmd += '--source {} '.format(pkt_details.get("source"))
        cmd += '--destination {} '.format(pkt_details.get("destination"))
        cmd += '--type {} '.format(pkt_details.get("type"))
        cmd += '--code {} '.format(pkt_details.get("code"))
        cmd += '--vlan {} '.format(pkt_details.get("vlan"))
        cmd += '--bts_id {} '.format(get_config_variable(['bts_id']))
        cmd += '--speed {} '.format(pkt_details.get("speed"))
        cmd += '--duration {} '.format(pkt_details.get("duration"))
        cmd += '--pkt_count {} '.format(pkt_details.get("packets"))
        cmd += '--pad_str {} '.format(self.pad)
        if pkt_details.get("dhcp_options"):
            pkt_details['dhcp_options'] = self._create_dhcp_opt_value(pkt_details['dhcp_options'])
        cmd += '--dhcp_options {}'.format(pkt_details.get("dhcp_options", ""))
        return cmd

    def _create_dhcp_opt_value(self, opt_dict):
        # This function converts a dict (i.e., dhcp_options, taken from traffic profile) to a string that can be used to edit scapy commands
        opt_str = ""
        for key, val in opt_dict.items():
            val_qt = "\'"
            try:
                if val.isdigit():
                    opt_dict[key] = int(val)
            except AttributeError:
                pass
            if not isinstance(opt_dict[key], str):
                val_qt = ""
            opt_str += "(\'" + str(key) + "\'," + val_qt + str(val) + val_qt + "),"
        return opt_str[:-1]

    def _send_traffic(self, profile):
        # traffic_profile = self._get_traffic_profile_from_profile(profile)
        tcpdump_pid = self.start_tcpdump_capture(get_config_variable(['generators', self.device, 'interface']))
        scapy_script_command = self.build_scapy_send_traffic_script_command(profile)
        out, err = self.session.execute_command(scapy_script_command, return_stderr=True)
        logger.debug(out, err)
        self.stop_tcp_dump_capture(tcpdump_pid=tcpdump_pid)
        speed_attained, duration = self.get_packet_speed(pid=tcpdump_pid, protocol=get_config_variable(['traffic_profiles', profile, 'protocol']))
        self._delete_capture_file()
        return speed_attained, duration

