    def _send_commands_to_scapy(self, count, time_to_sleep, profile):
        logger.debug("sending commands to scapy....")
        self._send_packets(count, time_to_sleep)

    def _replace_robot_variable_in_pkt_details(self, pkt_details, profile):
        logger.info("Pkt details :: {}".format(str(pkt_details)))
        for detail in list(pkt_details.keys()):
            if re.search(r"\$\{.*\}", str(pkt_details[detail])):
                pkt_details[detail] = get_config_variable(['traffic_profiles', profile, detail])
        return pkt_details

    def _send_l3_packets(self, count, time_to_sleep):
        logger.debug("sending L3 packets....")
        command_list = ['iter = 0']
        for command in command_list:
            self.session.write(command)
        self.session.read_until('>>>')
        self.session.write('while iter < {0}:'.format(count))
        self.session.read_until('...')
        self.session.write('        l=socket_l3.send(pe);iter=iter+1;sleep({0})'.format(time_to_sleep))
        self.session.read_until('...')
        self.session.write('')
        self.session.set_client_configuration(timeout='10 minutes')
        self.session.read_until('>>>')

    def login_to_scapy_pc(self, user, ip, password, prompt):
        logger.debug("logging to scapy pc....")
        if user == 'None' or ip == 'None':
            raise Exception("Invalid login credentials")
        pc_session = SSHLibrary.SSHLibrary()
        try:
            pc_session.open_connection(host=ip, prompt=prompt)
            sleep(5)
            self._ssh_auth_options(pc_session, user, password)
        except Exception as error_login:
            raise Exception("SSH Connection to scapy failed due to {}".format(error_login))
        self._is_user_root(pc_session)
        return pc_session

    def _ssh_auth_options(self, ssh_handle, user, password=None):
        if password is not None:
            logger.info("Performing password based login")
            ssh_handle.login(username=user, password=password)
        else:
            logger.info("Performing key based login")
            ssh_handle.login_with_public_key(username=user, keyfile='/home/ute/.ssh/authorized_keys',
                                             look_for_keys=True)

    def _is_user_root(self, ssh_handle):
        out, err, rc = ssh_handle.execute_command('id', return_stderr=True, return_rc=True)
        matches = re.finditer(r'uid=(\d+)', out, re.MULTILINE | re.DOTALL | re.IGNORECASE)
        for match in matches:
            self.root = 'root' if match.group(1) == 0 else 'non-root'
        logger.info("User has logged in as {}".format(self.root))

    def exit_scapy_interface(self):
        logger.debug("exiting scapy interface...")
        self.session.write('exit()')
        self.session.read_until(get_config_variable(['generators', self.device, 'prompt']))

    def start_tcpdump_capture(self, interface=None):
        logger.debug("starting tcpdump capture....")
        self.pcap_file = '{home}/tcpdump_capture_{btsid}.pcap'.format(home=self.home_path, btsid=self.bts_id)
        # tcpdump_cmd = self.sudo_dict.get(self.root) + ' tcpdump -i {0} src {1} and dst {2} -w {3} >/dev/null 2>/dev/null & echo $!'.format(interface, src, dest, self.pcap_file)
        pad_hex = '0x' + "".join("{:02x}".format(ord(c)) for c in self.pad)
        pad_pos = self.packet_len - 4
        tcpdump_cmd = self.sudo_dict.get(
            self.root) + ' tcpdump -i {} -xx ether[{}:4]=={} -w {} >/dev/null 2>/dev/null' \
                         ' & echo $!'.format(interface, pad_pos, pad_hex, self.pcap_file)
        logger.debug('Capturing tcpdump with command : {0}'.format(tcpdump_cmd))
        out, err, rc = self.session.execute_command(tcpdump_cmd, return_stderr=True, return_rc=True)
        logger.debug("tcpdump exection output:".format(out))
        out, err = out.strip(), err.strip()
        if rc == 0:
            logger.debug("tcpdump exection output:".format(out))
            return out
        else:
            raise Exception("Error in starting tcpdump:{}".format(err))

    def stop_tcp_dump_capture(self, tcpdump_pid):
        sleep(7)
        self.session.execute_command("sudo kill {}".format(tcpdump_pid))

    def _delete_capture_file(self):
        self.session.execute_command("rm -f tcpdump_capture_{0}.pcap".format(self.bts_id))
        self.session.execute_command("rm -f tcpdump_capture_{0}.txt".format(self.bts_id))

    def get_packet_speed(self, pid=None, protocol=None):
        logger.debug("getting packet speed....")
        # home_folder = expanduser("~")
        pcap_txt_file = self.home_path + '/tcpdump_capture_' + self.bts_id + '.txt'
        # pcap_filename = home_folder + '/tcpdump_capture_' + btsid + '.pcap'
        self.session.get_file(self.pcap_file, 'execution_logs/')
        out, err, rc = self.session.execute_command(self.sudo_dict.get(self.root) + ' tcpdump -r {0} -ttttt >{1}'.format(self.pcap_file,pcap_txt_file), return_stderr=True, return_rc=True)
        if rc == 1:
            raise Exception("Error in generating tcpdump text file:{}".format(err))
        self.session.get_file(pcap_txt_file, 'execution_logs/')
        if os.stat('execution_logs/tcpdump_capture_' + self.bts_id + '.txt').st_size == 0:
            raise Exception("Generated tcpdump text file is empty. No packets were sent.")
        delta_t = self.get_delta_time(pcap_txt_file, protocol)
        self.session.start_command('cat {0} | wc -l'.format(pcap_txt_file))
        packets = self.session.read_command_output()
        logger.debug('Number of packets sent :{}'.format(packets))
        speed = int(packets) / delta_t
        logger.debug('Speed Achieved is about : {0} per second'.format(speed))
        return speed, delta_t

    def get_delta_time(self, filename, protocol):
        logger.debug("getting delta time....")
        # grep_command = 'grep -i {0} {1} | tail -n 1'.format(protocol, filename)
        grep_command = 'tail -n 1 {}'.format(filename)
        self.session.start_command(grep_command)
        last_packet = self.session.read_command_output()
        logger.debug("Last Packet string: {}".format(last_packet))
        if last_packet == '':
            raise Exception("Protocol {} not found in captured data".format(protocol))
        time_str = last_packet[:15]
        logger.debug("Time string: {}".format(time_str))
        milli_seconds_str = time_str.split(".")[1]
        h_m_s_str = time_str.split(".")[0]
        h_m_s = h_m_s_str.split(":")
        milli_seconds = int(milli_seconds_str) / float(1000000)
        delta_time = int(h_m_s[0]) * 60 * 60 + int(h_m_s[1]) * 60 + int(h_m_s[2]) + milli_seconds
        logger.debug('Time in which packets were sent : {0}'.format(delta_time))
        return delta_time

    def _get_scapy_pc_home_path(self, user):
        out = self.session.execute_command('getent passwd {user} | cut -d: -f6 '.format(user=user))
        logger.debug('Scapy PC HOME path: {} ##'.format(out))
        return out

    def traffic_capture_and_replay(self, capture_interface, replay_interface, capture_filter, num_pkts_to_send, delay, **kwargs):
        modify_string = None
        scapy_script = os.path.abspath(os.path.join(__file__, os.pardir, 'scapy_replay.py'))
        self.session.put_file(scapy_script, "scapy_replay.py")
        for key, value in list(kwargs.items()):
            modify_string = str(key) + '=' + str(value)
            modify_string += ','
        replay_command = "python scapy_replay.py -c {0} -r {1} -f \"{2}\" -n {3} -d {4}".format(capture_interface, replay_interface, capture_filter, num_pkts_to_send, delay)
        if modify_string:
            replay_command = replay_command + ' -m ' + modify_string[:-1]
        logger.debug("Command: {0}".format(replay_command))
        out, err = self.session.execute_command(replay_command, return_stderr=True)
        logger.debug(out, err)